import {feeEstimate,minimumOffer,moneyCents} from './fee-model.js';
import {icon} from './icons.js';
const $=s=>document.querySelector(s),money=cents=>'¥'+(cents/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}),shares={buyer:'归买家',split:'各半',seller:'归卖家'};
$('#calculator-view').innerHTML=`<div class="fee-workspace"><div class="fee-intro"><span class="fee-reference-tag">还价与补差额</span><p>分别看清平台成交价、额外补差与双方收支。</p></div><div class="fee-state" hidden><select id="calc-mode" data-native-state><option value="quote">填挂价</option><option value="target">填卖家到手</option></select></div><div class="calculator-grid"><section class="card calculator fee-input-card"><div class="fee-tabs" role="group" aria-label="输入方式"><button type="button" data-fee-mode="quote" aria-pressed="true">填挂价</button><button type="button" data-fee-mode="target" aria-pressed="false">填卖家到手</button></div><div class="fee-card-body"><h2>输入金额</h2><label class="fee-field"><span id="amount-label">挂价（CBG 上架价）</span><div class="fee-money-field"><input id="amount" type="number" inputmode="decimal" min="0.01" step="0.01" max="100000000" value="3000" placeholder="请输入金额" aria-describedby="fee-rule-note"><span class="fee-unit">元</span></div></label><p id="fee-suggested" class="fee-suggested" hidden></p><div id="bargain-fields"><label class="fee-field">还价金额<div class="fee-money-field"><input id="offer" type="number" inputmode="decimal" min="0.01" step="0.01" max="100000000" value="2400" placeholder="请输入还价"><span class="fee-unit">元</span></div></label><div class="fee-rebate-bar"><span id="discount-display">折数 0.8000000000</span><button type="button" class="button secondary" data-discount="0.8">一键八折</button></div></div><p id="fee-rule-note" class="fee-rule-note">参考试算口径：手续费率 8%，还价下限八折。</p><p class="fee-precision-note">内部计算保留精度，结果显示到分。实际费用及可还价范围请以藏宝阁订单为准。</p></div></section><section class="fee-results-column"><div class="card fee-share-card"><h2>省下的手续费归谁</h2><div class="fee-share-group" role="group" aria-label="手续费分配">${Object.entries(shares).map(([value,label])=>`<button type="button" data-fee-share="${value}" aria-pressed="${value==='buyer'}">${label}</button>`).join('')}</div></div><section class="card calc-result"><div class="fee-result-heading"><h2 id="result-title">结果 · 归买家</h2><button type="button" class="fee-copy" id="copy-fee" aria-label="复制试算结果">${icon('copy')}<span>复制结果</span></button></div><div id="fee-error" class="fee-error" role="status" hidden></div><div id="fee-valid-result"><div class="fee-highlight"><span>买家需补差额 <small>额外支付</small></span><strong id="result-value">—</strong></div><div id="result-breakdown"></div><p id="fee-baseline" class="fee-baseline"></p></div><p id="fee-message" class="fee-message" role="status"></p><textarea id="fee-summary" class="fee-copy-text" readonly aria-label="试算结果文本"></textarea></section></section></div><aside class="fee-safety"><span>${icon('info')}</span><p><strong>交易提醒</strong>补差额属于平台外支付，需自行承担风险。确认交易对象、金额与款项状态后再操作；试算结果仅供核对收支。</p></aside></div>`;
let mode='quote',share='buyer',automatic=true,values={quote:'3000',target:'2760'},lastResult=null;
function syncOffer(){if(!automatic)return;try{$('#offer').value=(minimumOffer(mode,$('#amount').value)/100).toFixed(2)}catch{$('#offer').value=''}$('#offer').dispatchEvent(new Event('change',{bubbles:true}))}
function row(label,value,extra='',emphasis=false){return `<div class="breakdown-row${emphasis?' fee-row-emphasis':''}"><span>${label}</span><strong>${money(value)}${extra?`<small>${extra}</small>`:''}</strong></div>`}
function render(){
 $('.fee-tabs').dataset.mode=mode;$('.fee-share-group').dataset.share=share;
 $('#copy-fee').disabled=true;$('#fee-suggested').hidden=mode!=='target';$('#result-title').textContent='结果 · '+shares[share];$('#amount-label').textContent=mode==='target'?'卖家想到手（原始基准）':'挂价（CBG 上架价）';lastResult=null;
 for(const b of document.querySelectorAll('[data-fee-mode]'))b.setAttribute('aria-pressed',String(b.dataset.feeMode===mode));for(const b of document.querySelectorAll('[data-fee-share]'))b.setAttribute('aria-pressed',String(b.dataset.feeShare===share));
 try{
  const r=feeEstimate({mode,amount:$('#amount').value,offer:$('#offer').value,share});lastResult=r;$('#fee-error').hidden=true;$('#fee-valid-result').hidden=false;$('#amount').removeAttribute('aria-invalid');$('#offer').removeAttribute('aria-invalid');$('#fee-suggested').textContent='建议 CBG 挂价 '+money(r.quote);$('#discount-display').textContent='折数 '+r.discount;
  $('#result-value').textContent=money(r.supplement);$('#result-breakdown').innerHTML=(mode==='target'?row('建议 CBG 挂价',r.quote):'')+row('平台成交价（还价）',r.offer)+row('平台手续费（8%）',r.fee)+row('买家实际付款',r.buyerTotal,r.buyerSaving?'节省 '+money(r.buyerSaving):'与原价成交相同',true)+row('卖家实际到手',r.sellerNet,r.sellerGain?'增加 '+money(r.sellerGain):'与原始基准相同',true);
  $('#fee-baseline').textContent='原价成交基准：买家付 '+money(r.quote)+'，卖家到手 '+money(r.originalNet)+'。省下手续费共 '+money(r.saving)+'。';$('#fee-message').textContent='';$('#fee-summary').value=['还价与补差额试算 · '+shares[share],'输入方式：'+(mode==='target'?'填卖家到手':'填挂价'),'原挂价：'+money(r.quote),'平台成交价：'+money(r.offer),'平台手续费：'+money(r.fee),'买家补差额：'+money(r.supplement),'买家实际付款：'+money(r.buyerTotal),'卖家实际到手：'+money(r.sellerNet),'省下手续费：'+money(r.saving),'试算口径：费率8%、八折下限，实际以订单为准。'].join('\n');$('#copy-fee').disabled=false;
 }catch(error){$('#fee-valid-result').hidden=true;$('#fee-error').hidden=false;$('#fee-error').textContent=error.message;$('#fee-summary').value='';$('#fee-suggested').hidden=true;$('#discount-display').textContent='折数 —';$('#fee-message').textContent='调整输入后会自动重新计算。';let primaryValid=false;try{primaryValid=moneyCents($('#amount').value)>0}catch{}$('#amount').setAttribute('aria-invalid',String(!primaryValid));$('#offer').setAttribute('aria-invalid',String(primaryValid))}
}
function setMode(value){if(!['quote','target'].includes(value))return;values[mode]=$('#amount').value;mode=value;$('#calc-mode').value=mode;$('#amount').value=values[mode];$('#amount').dispatchEvent(new Event('change',{bubbles:true}));automatic=true;syncOffer();render()}
$('#calc-mode').onchange=()=>setMode($('#calc-mode').value);document.querySelectorAll('[data-fee-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.feeMode));document.querySelectorAll('[data-fee-share]').forEach(b=>b.onclick=()=>{share=b.dataset.feeShare;render()});
$('#amount').addEventListener('input',()=>{values[mode]=$('#amount').value;syncOffer();render()});$('#offer').addEventListener('input',()=>{automatic=false;render()});$('[data-discount]').onclick=()=>{automatic=true;syncOffer();render()};
$('#copy-fee').onclick=async()=>{if(!lastResult)return;try{await navigator.clipboard.writeText($('#fee-summary').value);$('#fee-message').textContent='试算结果已复制。'}catch{$('#fee-summary').classList.add('is-visible');$('#fee-summary').focus();$('#fee-summary').select();$('#fee-message').textContent='请复制下方已选中的结果。'}};
window.addEventListener('fee-product',e=>{if(!Number.isSafeInteger(e.detail)||e.detail<=0)return;values.quote=(e.detail/100).toFixed(2);if(mode==='quote')$('#amount').value=values.quote;setMode('quote');window.dispatchEvent(new CustomEvent('navigate-view',{detail:'calculator'}))});render();
